import {resourceLedgerView} from './expedition-resource-ledger.mjs';
import {FOUNDRY_OBJECTIVES,foundryAssessment} from './expedition-foundry-contract.mjs';import {GEAR} from './expedition-data.mjs';import {equipmentStats} from './expedition-equipment-view.mjs';
export function foundryContracts(g){return `<section class="guild-panel foundry-contracts" data-guild-pane="contracts"><p class="eyebrow">锈潮铸库 / 一次性委托</p><h2>带回图纸，也带回同行的人。</h2><p>每次正常铸库出征自动核对，不必另接任务。首次达成随结算获得20金币与指定遗物，进入公会仓库后再分配；已完成目标不重复发奖。没有新增货币或额外经验。</p><div class="equipment-catalog">${Object.entries(FOUNDRY_OBJECTIVES).map(([id,o])=>`<article class="equipment-item" data-foundry-objective="${id}"><h3>${o.name} · ${(g.foundry?.claimed||[]).includes(id)?'已完成':'未完成'}</h3><p>${o.desc}</p><p>定向奖励：${GEAR[o.gear].name} + ${o.gold}金币</p><small>${equipmentStats(o.gear)}</small></article>`).join('')}</div><button data-foundry-prepare="true">准备铸库远征 →</button><p>实验、试演与历史重演只显示条件，不发奖；达成后仍需领取正常公会结算。通关基础奖励与随机固定装备池继续保留。</p></section>`;}
export function foundryOutcomeView(report){if(report.config.expedition==='palisade')return '<p class=eyebrow>折潮哨垒 / 三场用料复盘</p><h2>先拆来源，还是绕过接招？</h2><p>敌方援护用敌方个人法力，不扣己方材料；实际攻击按真正受击者结算，原目标另见援护记录。成功接招后也可能闪避或承伤，次数不能换算为避免伤害。</p>'+resourceLedgerView(report);if(report.config.expedition==='inquest')return '<p class=eyebrow>镜心问堂 / 用料复盘</p><h2>护住心声，也留出法力。</h2><p>心智抵抗按每次受击支付法力，不占普通行动；定心吟占预备行动。心理攻击不附状态，净化不能撤销伤害。共享用料与个人防御法力分开记录。</p>'+resourceLedgerView(report);if(report.config.expedition==='shoals')return '<p class=eyebrow>漂流群礁 / 海图远征</p><h2>三场连续用料</h2><p>海图在出发前固定，战斗种子只影响实际检定；没有隐藏通路费用，每图不额外发首通奖励。成功领取后更新勘探册。</p>'+resourceLedgerView(report);if(report.config.expedition==='theater')return '<p class=eyebrow>失声剧场 / 用料复盘</p><h2>为攻击节奏支付什么？</h2><p>净化成功占用预备并消耗符纸；无负面目标的跳过不付费。挫志附着与采用该效果的攻击分别记录，不能把次数换算成避免伤害。</p>'+resourceLedgerView(report);if(report.config.expedition==='courier')return '<p class=eyebrow>沉船邮路 / 用料复盘</p><h2>让回信抵达岸上</h2><p>节拍增加行动机会，但仍要支付技能自己的法力与物资。来源倒下只停止之后刷新，已施放效果按期限结束；可从支援复盘和行动队列追溯。</p>'+resourceLedgerView(report);if(report.config.expedition==='foundrywatch')return '<p class=eyebrow>封库守望 / 用料复盘</p><h2>三场持续分工</h2><p>按实际施法与资源跳过检查分工和续航；此路线不触发铸库图纸或归航委托。</p>'+resourceLedgerView(report);const p=foundryAssessment(report);if(!p)return '';const m=p.metrics;return `<p class="eyebrow">铸库委托 / 本战报条件</p><h2>图纸与归航</h2><p>${m.won?'已通关':'未通关'} · ${m.alive}/6人生还 · 已遭遇${m.rounds}回合 · 剩余${m.rune}符纸/${m.arrow}箭矢 · 正式队员总生命 ${m.hp}/${m.maxHp}（${m.hpPercent}%）</p><div class="departure-cards">${Object.entries(FOUNDRY_OBJECTIVES).map(([id,o])=>`<article><h3>${o.name} · ${p.goals[id]?'本次达到条件':'本次未达到'}</h3><p>${o.desc}</p><small>首次正常结算：${GEAR[o.gear].name} + ${o.gold}金币</small></article>`).join('')}</div><p>这里只说明这份已发生战报的条件，不预测下次。实验、试演或历史重演不发奖；是否为首次完成与实际奖励，以公会待结算和已完成记录为准。</p>`+resourceLedgerView(report);}
